<?php
require __DIR__.'/_bootstrap.php';
$counts=[];foreach(['users'=>'users','active trains'=>'trains WHERE is_active=1','active schedules'=>'schedules WHERE is_active=1','confirmed bookings'=>'booking_groups WHERE status="Confirmed"','confirmed passengers'=>'bookings WHERE status="Confirmed"'] as $label=>$table){$counts[$label]=(int)$pdo->query('SELECT COUNT(*) FROM '.$table)->fetchColumn();}
$recent=$pdo->query('SELECT g.booking_ref,g.journey_date,g.status,g.booking_time,u.full_name AS host,t.train_name,r.route_name FROM booking_groups g JOIN users u ON u.user_id=g.host_user_id JOIN schedules sc ON sc.schedule_id=g.schedule_id JOIN trains t ON t.train_id=sc.train_id JOIN routes r ON r.route_id=sc.route_id ORDER BY g.booking_time DESC LIMIT 12')->fetchAll();
$pageTitle='Admin dashboard';require __DIR__.'/../includes/header.php';?>
<section class="content"><span class="eyebrow">CONTROL PANEL</span><h1>Admin dashboard</h1><div class="features"><?php foreach($counts as $label=>$count):?><article><b><?=e(number_format($count))?></b><h3><?=e(ucfirst($label))?></h3></article><?php endforeach?></div><p class="admin-links"><a class="button" href="<?=e(app_url('admin/manage.php'))?>">Manage system data</a> <a class="button pale" href="<?=e(app_url('admin/bookings.php'))?>">View bookings</a> <a class="button pale" href="<?=e(app_url('admin/credentials.php'))?>">Admin credentials</a></p><h2>Recent bookings</h2><div class="list"><?php foreach($recent as $row):?><article><div><span class="tag"><?=e($row['status'])?> · <?=e($row['booking_ref'])?></span><h3><?=e($row['host'])?> · <?=e($row['train_name'])?></h3><p><?=e($row['route_name'])?> · <?=e($row['journey_date'])?> · <?=e($row['booking_time'])?></p></div></article><?php endforeach?><?php if(!$recent):?><article>No bookings have been made.</article><?php endif?></div></section>
<?php require __DIR__.'/../includes/footer.php'; ?>
